a.record('pfp/domain/exact/__init__.py',1,62,'Read complete exact-kernel lazy export map. Access imports/cache a named math, digest, wire or previously reviewed rational owner; unknown attributes refuse. This routing includes both Q always-p/q and Fraction integer-without-slash wire dialects, so the package does not define one universal canonical rational spelling. No mathematical guarantee follows from re-export.',['lazy arithmetic routing','distinct rational dialects'])
a.record('pfp/domain/exact/errors.py',1,25,'Read local exact refusal taxonomy. ExactRefusal extends the domain exception and retains arbitrary code/detail; ExactError is a subclass with no extra validation. The class carries failure data, not proof of a condition or exhaustive catch policy. DomainError dependency was separately read-vetted without package initialization.',['refusal data','error propagation'])
a.record('pfp/domain/exact/alg.py',1,161,'Read rational interval arithmetic, root isolation, algebraic comparison/sign and limits. Closed interval products take four extrema; Alg uses monic squarefree polynomial and one-root half-open interval. Mathematical equality is alg_equal via gcd/intersection, while __eq__ compares presentation fields. isolate squarefrees first and recursively bisects without a global operation budget; comparison/sign have4096 refinement caps. Constructor accepts a mutable list despite tuple annotation and leaves it attached: probe changes polynomial from x-1 to x-2 and changes represented value after construction. Input endpoints/coefficient types rely mostly on downstream operations. General root_count endpoint defect does not automatically invalidate squarefree isolate/Alg construction paths.',['isolating interval contract','semantic vs presentation equality','mutable certificate data','bounded refusal','squarefree caller scope'])
a.record('pfp/domain/exact/poly.py',1,160,'Read all rational polynomial operations, Euclidean division/gcd, squarefree reduction, Sturm variations and bound. Arithmetic is low-to-high coefficients with trim and no coefficient/size validation beyond Q operations. root_count claims distinct roots for arbitrary polynomials but feeds the unreduced polynomial to a Sturm chain and simply removes zero signs at endpoints. For(x-1)^2(x-2), this returns0 on(1,3] instead of1 and2 on(0,1] instead of1; ordinary nonroot endpoints(0,3] returns2. Squarefree reduction or suitable endpoint handling is needed for this public contract. Cauchy bound is conservatively max coefficient magnitude+2.',['Sturm endpoint defect','exact arithmetic','squarefree precondition','resource assumptions'])
a.record('pfp/domain/exact/linalg.py',1,130,'Read shape checking and all injected linear-algebra calls. as_matrix requires Q entries and rectangular rows; square/symmetry checks precede determinant, characteristic polynomial and positivity interfaces. Algorithms and returned values are trusted from one mutable process-global port; no runtime port conformance, returned rank range, minor count, rational result or positivity proof is checked. first_nonpositive_minor accepts an empty returned minor sequence as success. Sylvester criterion is valid for real symmetric matrices when all leading minors are correctly computed; this facade does not certify its injected implementation. Unbound port explicitly refuses.',['injected trusted algorithm','shape gates','unchecked returned witnesses','Sylvester assumptions'])
a.record('pfp/domain/exact/digest.py',1,71,'Read canonical JSON prewalk and SHA wrappers. The declared sorted compact ASCII profile refuses floating values recursively and nonexact-str mapping keys, with json serialization rejecting unsupported values. Tuples/lists intentionally share JSON array representation; no injectivity over arbitrary Python objects or cryptographic collision impossibility follows. Custom Mapping objects may pass the prewalk but fail json serialization; cycles/depth/size remain unbounded and failure is not normalized to ExactError throughout. Digest binds supplied bytes/shape only, not truth or provenance.',['serialization profile','float refusal','digest ceiling','resource limits'])
a.record('pfp/domain/exact/wire.py',1,102,'Read Fraction wire and duality-gap record. Serialization is canonical, but from_wire strips whitespace and normalizes arbitrary int/fraction spellings rather than requiring canonical input; seven alternate spellings accepted here are refused by shared_kernel.parse_exact. DualityGap constructor checks only Fraction types and admits inconsistent objective/gap/optimal triples. compute marks equal objective scalars optimal without primal/dual feasibility, constraint binding or weak-duality hypotheses. This is an exact scalar difference calculator, not a standalone optimization certificate. Local usage census found only public exports, not a demonstrated accepting workflow caller.',['canonical parse mismatch','inconsistent certificate fields','optimality requires feasibility','caller scope'])
notes=a.read('_notes.json');probes=a.read('_exact_probes.json');notes['controls'].extend(probes['controls'])
def evidence(path,lines):return {'path':path,'sha256':a.row(path)['sha256'],'lines':lines}
for id,title,statement,path,lines,cid in [
('PFPDOMAIN-F001','Distinct-root count fails at repeated-root endpoints','root_count documents distinct roots in(lo,hi] but misses squarefree normalization/endpoint handling. For(x-1)^2(x-2), observed0 instead of1 on(1,3] and2 instead of1 on(0,1]. isolate and Alg constructors squarefree their input or reject repeated factors, so these examples refute the public root_count contract without automatically refuting those guarded paths.','pfp/domain/exact/poly.py',[[103,127]],'PFPDOMAIN-C001'),
('PFPDOMAIN-F002','A frozen algebraic number retains mutable polynomial input','Alg accepts a list because it only compares trim(poly) with tuple(poly), then stores the original mutable object. Mutating the caller list from x-1 to x-2 changes alg_equal results while the Alg instance remains the same frozen object. Primary internal constructors use tuples; the malformed-but-accepted public constructor path is the demonstrated failure.','pfp/domain/exact/alg.py',[[62,88],[114,120]],'PFPDOMAIN-C002'),
('PFPDOMAIN-F003','RationalWire accepts multiple canonical input spellings','from_wire advertises canonical parsing but accepts whitespace, leading zeros, denominator-one and nonreduced fractions, negative denominator, plus sign and negative zero. It normalizes all through Fraction, unlike the strict shared rational parser. This is a representation-binding gap at the public API; no workflow exploitation is demonstrated.','pfp/domain/exact/wire.py',[[18,54]],'PFPDOMAIN-C003'),
('PFPDOMAIN-F004','Scalar duality-gap equality is not an optimality certificate','RationalDualityGap permits inconsistent fields via its constructor and compute sets is_optimal solely from equality of two scalar objectives. Feasible primal/dual witnesses and the same constrained problem are absent. An inconsistent(1,0,0,True) record is accepted. Equal values can be an arithmetic gap result only; optimality requires separately validated feasibility and weak duality. No concrete workflow accepting this record has yet been found.','pfp/domain/exact/wire.py',[[62,87]],'PFPDOMAIN-C004')]:
 notes['findings'].append({'id':id,'title':title,'statement':statement,'evidence':[path],'source_evidence':[evidence(path,lines)],'control_ids':[cid],'status':'confirmed_bounded_source_and_probe','limits':'No native/provider execution; scoped Python3.14.2 probe with read-vetted modules and inert namespace packages.'})
for path,report in [('pfp/domain/exact/q.py','dag/reviews/pfp_audit.json'),('pfp/domain/exceptions.py','dag/reviews/additional_paper_006_support.json')]:
 p=a.ROOT/path;notes['external_dependencies_consulted'].append({'path':path,'sha256':a.sha(p),'reviewed_lines':[[1,len(p.read_text(encoding='utf-8-sig').splitlines())]],'status':'existing_full_owner_re_read_for_transitive_probe_safety','prior_report':report,'coverage_credit':'none_in_remaining427'})
notes['limits'][2]='No provider/private benchmark/seed/key/answer access or native build. Only read-vetted exact owners were executed in isolated namespace contexts by the recorded bounded probes.'
init=a.read('_initial_reconciliation.json');assert all(x['coverage_status_at_reconciliation'] not in ('full_source_read','full_text_source_review_recorded') for x in init['files'])
notes['initial_coverage_status_counts']=dict(collections.Counter(x['coverage_status_at_reconciliation'] for x in init['files']))
